content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  -webkit-font-smoothing: antialiased;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

.header {
  margin-bottom: 2rem;
  text-align: center;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  color: var(--text-main);
  margin: 0 0 0.5rem 0;
}

.subtitle {
  font-size: 1rem;
  color: var(--text-muted);
  margin: 0;
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.5rem;
  margin-bottom: 2rem;
  border: 1px solid var(--border-color);
}

.chart-wrapper {
  width: 100%;
  height: 400px;
}

.controls {
  display: flex;
  gap: 0.5rem;
  justify-content: center;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}

.btn {
  background-color: #ffffff;
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  padding: 0.5rem 1rem;
  border-radius: 8px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn:hover {
  background-color: #f1f5f9;
  color: var(--text-main);
}

.btn.active {
  background-color: var(--primary-color);
  color: #ffffff;
  border-color: var(--primary-color);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.5rem;
}

.stat-card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.25rem;
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.stat-card h3 {
  margin: 0;
  font-size: 1.1rem;
  color: var(--text-main);
}

.stat-card p {
  margin: 0;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-color);
}

@media (max-width: 768px) {
  .app-container {
    padding: 1rem;
  }
  .title {
    font-size: 1.5rem;
  }
  .chart-wrapper {
    height: 300px;
  }
}

export interface MonthlyStoreData {
  month: string;
  渋谷店: number;
  新宿店: number;
  銀座店: number;
}

export type StoreKey = '渋谷店' | '新宿店' | '銀座店';

import { useState } from 'react';
import { ResponsiveContainer, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend } from 'recharts';
import { MonthlyStoreData, StoreKey } from './types';
import './index.css';

const initialData: MonthlyStoreData[] = [
  { month: '1月', 渋谷店: 4200, 新宿店: 5100, 銀座店: 3200 },
  { month: '2月', 渋谷店: 3800, 新宿店: 4800, 銀座店: 3000 },
  { month: '3月', 渋谷店: 4600, 新宿店: 5900, 銀座店: 3800 },
  { month: '4月', 渋谷店: 5100, 新宿店: 6200, 銀座店: 4100 },
  { month: '5月', 渋谷店: 5500, 新宿店: 6700, 銀座店: 4500 },
  { month: '6月', 渋谷店: 4900, 新宿店: 6000, 銀座店: 3900 },
  { month: '7月', 渋谷店: 5800, 新宿店: 7100, 銀座店: 4800 },
  { month: '8月', 渋谷店: 6200, 新宿店: 7500, 銀座店: 5200 },
  { month: '9月', 渋谷店: 5300, 新宿店: 6400, 銀座店: 4300 },
  { month: '10月', 渋谷店: 5700, 新宿店: 6900, 銀座店: 4600 },
  { month: '11月', 渋谷店: 6000, 新宿店: 7300, 銀座店: 4900 },
  { month: '12月', 渋谷店: 6800, 新宿店: 8200, 銀座店: 5800 },
];

export default function App() {
  const [selectedStore, setSelectedStore] = useState<StoreKey | 'すべて'>('すべて');

  const totalVisitors = (store: StoreKey) => {
    return initialData.reduce((acc, cur) => acc + cur[store], 0);
  };

  const avgVisitors = (store: StoreKey) => {
    return Math.round(totalVisitors(store) / initialData.length);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">店舗別月別来客数比較</h1>
        <p className="subtitle">渋谷店・新宿店・銀座店の2023年度来客数推移グラフ</p>
      </header>

      <div className="card">
        <div className="controls">
          <button
            className={`btn ${selectedStore === 'すべて' ? 'active' : ''}`}
            onClick={() => setSelectedStore('すべて')}
          >
            すべて表示
          </button>
          <button
            className={`btn ${selectedStore === '渋谷店' ? 'active' : ''}`}
            onClick={() => setSelectedStore('渋谷店')}
          >
            渋谷店
          </button>
          <button
            className={`btn ${selectedStore === '新宿店' ? 'active' : ''}`}
            onClick={() => setSelectedStore('新宿店')}
          >
            新宿店
          </button>
          <button
            className={`btn ${selectedStore === '銀座店' ? 'active' : ''}`}
            onClick={() => setSelectedStore('銀座店')}
          >
            銀座店
          </button>
        </div>

        <div className="chart-wrapper">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={initialData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="month" stroke="#64748b" />
              <YAxis stroke="#64748b" />
              <Tooltip />
              <Legend />
              {(selectedStore === 'すべて' || selectedStore === '渋谷店') && (
                <Line type="monotone" dataKey="渋谷店" stroke="#4f46e5" strokeWidth={3} dot={{ r: 4 }} activeDot={{ r: 8 }} />
              )}
              {(selectedStore === 'すべて' || selectedStore === '新宿店') && (
                <Line type="monotone" dataKey="新宿店" stroke="#ec4899" strokeWidth={3} dot={{ r: 4 }} activeDot={{ r: 8 }} />
              )}
              {(selectedStore === 'すべて' || selectedStore === '銀座店') && (
                <Line type="monotone" dataKey="銀座店" stroke="#10b981" strokeWidth={3} dot={{ r: 4 }} activeDot={{ r: 8 }} />
              )}
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="stats-grid">
        {(selectedStore === 'すべて' || selectedStore === '渋谷店') && (
          <div className="stat-card">
            <h3>渋谷店 年間総来客数</h3>
            <p>{totalVisitors('渋谷店').toLocaleString()} 人</p>
            <span style={{ fontSize: '0.85rem', color: 'var(--text-muted)' }}>月平均: {avgVisitors('渋谷店').toLocaleString()} 人</span>
          </div>
        )}
        {(selectedStore === 'すべて' || selectedStore === '新宿店') && (
          <div className="stat-card">
            <h3>新宿店 年間総来客数</h3>
            <p>{totalVisitors('新宿店').toLocaleString()} 人</p>
            <span style={{ fontSize: '0.85rem', color: 'var(--text-muted)' }}>月平均: {avgVisitors('新宿店').toLocaleString()} 人</span>
          </div>
        )}
        {(selectedStore === 'すべて' || selectedStore === '銀座店') && (
          <div className="stat-card">
            <h3>銀座店 年間総来客数</h3>
            <p>{totalVisitors('銀座店').toLocaleString()} 人</p>
            <span style={{ fontSize: '0.85rem', color: 'var(--text-muted)' }}>月平均: {avgVisitors('銀座店').toLocaleString()} 人</span>
          </div>
        )}
      </div>
    </div>
  );
}
